let cloudUser=null,cloudQueue=null,cloudStateError="",db,state,records=[],templates,current=null,pendingWorkbook=null,stream=null,autoTimer=null,cameraSession=null,cameraAuto=true,batchMode=false,batchDelay=3,batchCount=0,batchSeen=new Set(),resumeCamera=false,busy=false,token=null,keyTab='mc',activeCode='',resultQuery='',resultClass='',resultRoom='',resultTeacher='',resultStatus='',rawForCorners=null,manualCorners=[],cornerCanvas=null;
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint8Array(16)),x=>x.toString(16).padStart(2,'0')).join('');const now=()=>new Date().toISOString();const fresh=()=>({id:'workspace',examId:uid(),cfg:structuredClone(defaults),roster:[],keys:{},drive:{clientId:'',folderName:'Chấm Thi - Đặng Trần Côn',folderId:''}});
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
function request(req){return new Promise((res,rej)=>{req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error);});}
async function putLocal(store,value){return new Promise((res,rej)=>{let tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=res;tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error||Error('Không lưu được dữ liệu.'));});}
async function put(store,value){if(store==='records'&&state?.cloud&&value.examId===state.examId){value.cloudExam=true;value.cloudAccount=cloudUser?.id;value.cloudRecordId??=value.id;}await putLocal(store,value);if(store==='records'&&value.cloudExam)cloudQueue?.enqueue(value);}
function cloudDirty(){return !!state?.cloud&&state.cloud.snapshot!==setupFingerprint(state);}
async function persist(){await putLocal('meta',state);if(state.cloud&&cloudDirty()){if(!isManager(state.cloud.role))throw Error('Chỉ người phụ trách được sửa cấu hình kỳ thi online.');try{let{exam}=await api('exams/'+state.examId,{method:'PUT',body:JSON.stringify({cfg:state.cfg,roster:state.roster,keys:state.keys,revision:state.cloud.revision,closed:state.cloud.closed,unlock:state.cloud.locked&&!state.cfg.locked})});state.cfg=exam.cfg;state.roster=exam.roster;state.keys=exam.keys;state.cloud={...state.cloud,...cloudInfo(exam)};state.cloud.snapshot=setupFingerprint(state);cloudStateError='';await putLocal('meta',state);}catch(error){cloudStateError=error.message;toast('Đã lưu cấu hình trên thiết bị; chưa đồng bộ: '+error.message);}}}
function cloudInfo(exam){return{role:exam.role,scope:exam.scope,revision:exam.revision,closed:exam.closed,locked:exam.cfg.locked,assignment:exam.assignment};}
async function loadCloud(eid){let{user}=await api('me');cloudUser=user;let{exam}=await api('exams/'+eid),cache=await request(db.transaction('meta').objectStore('meta').get('cloud:'+user.id+':'+eid)),dirty=cache?.cloud&&cache.cloud.snapshot!==setupFingerprint(cache);state=dirty?cache:{...fresh(),...cache,id:'cloud:'+user.id+':'+eid,examId:eid,cfg:exam.cfg,roster:exam.roster,keys:exam.keys,cloud:cloudInfo(exam)};if(!dirty)state.cloud.snapshot=setupFingerprint(state);else cloudStateError='Có cấu hình trên thiết bị chưa đồng bộ. Đồng bộ để cập nhật, hoặc tải lại cấu hình online.';await putLocal('meta',state);await refreshCloudRecords();}
async function refreshCloudRecords(){if(!state.cloud)return;let offset=0;do{let response=await api('exams/'+state.examId+'/records?offset='+offset);for(let row of response.records){let serverId=row.id,old=records.find(r=>(r.cloudRecordId||r.id)===serverId&&r.cloudAccount===cloudUser.id);row.cloudRecordId=serverId;row.id=old?.id||'cache:'+cloudUser.id+':'+serverId;let pending=old?.cloudExam&&!old.cloudSummary&&old.cloudStamp!==old.updated+'|'+old.status;if(pending)continue;let value=old?.cloudRevision===row.cloudRevision?{...old,...row,cloudSummary:old.cloudSummary,groups:old.groups,cfg:old.cfg,key:old.key,rawAnswers:old.rawAnswers,edits:old.edits}:{...row};value.cloudExam=true;value.cloudAccount=cloudUser.id;value.cloudStamp=value.updated+'|'+value.status;await putLocal('records',value);records=records.filter(r=>r.id!==value.id);records.push(value);}offset=response.nextOffset;}while(offset!==null);}
function syncBadge(){let badge=$('#cloudSyncBadge');if(!badge||!state?.cloud)return;let pending=list().filter(r=>r.cloudExam&&!r.cloudSummary&&r.cloudStamp!==r.updated+'|'+r.status).length;badge.textContent=cloudStateError?'Cần đồng bộ cấu hình':pending?pending+' bài chờ đồng bộ':'Đã đồng bộ';badge.className='tag '+(pending||cloudStateError?'orange':'green');}
function cloudBanner(){return '<section class="cloud-banner"><div><b>Chấm trên thiết bị · GitHub Pages</b><p class="small">Nhập Excel, quét và lưu kết quả trên trình duyệt này. Chấm chung và phân quyền cần bản có backend.</p></div><a href="./team.html">Về chức năng chấm chung →</a></section>'; }
function unusedCloudBanner(){if(!state.cloud)return `<section class="cloud-banner"><div><b>Kỳ thi trên thiết bị</b><p class="small">Dữ liệu cũ được giữ nguyên. Có thể tạo bản online để dùng trên nhiều máy.</p></div><div class="actions"><a href="./team.html">Kỳ thi online →</a>${button('publish-cloud','Đưa kỳ thi lên online','secondary')}</div></section>`;return `<section class="cloud-banner"><div><b>${state.cloud.scope==='shared'?'Kỳ thi chung':'Kỳ thi riêng online'} · ${esc(state.cfg.name)}</b><p class="small">${esc(roleNames[state.cloud.role])} · ${esc([...(state.cloud.assignment?.classes||[]).map(v=>'Lớp '+v),...(state.cloud.assignment?.rooms||[]).map(v=>'Phòng '+v),(state.cloud.assignment?.sbds||[]).length?(state.cloud.assignment.sbds.length+' SBD'):null].filter(Boolean).join(', ')||'Toàn kỳ thi')}${state.cloud.closed?' · Đã đóng kỳ thi':''} · ${esc(cloudUser?.name||'')}${cloudStateError?'<br>'+esc(cloudStateError):''}</p></div><div class="actions"><span id="cloudSyncBadge" class="tag">Đồng bộ</span>${button('sync-cloud','Đồng bộ','secondary')}<a href="./team.html">Danh sách kỳ thi →</a>${cloudDirty()||state.cloud.stale?button('pull-cloud','Tải cấu hình online','ghost'):''}</div></section>`;}
function cloudGuard(edit=false,final=false){if(!state.cloud)return;if(state.cloud.stale&&!edit)throw Error('Đáp án online đã thay đổi. Tải cấu hình mới, chấm lại bài cũ rồi tiếp tục quét.');if(state.cloud.closed)throw Error('Kỳ thi đã đóng. Người phụ trách có thể mở lại trong Kỳ thi online.');if(state.cloud.role==='viewer')throw Error('Tài khoản chỉ có quyền xem.');if(edit&&!isManager(state.cloud.role))throw Error('Chỉ người phụ trách được sửa cấu hình.');if(final&&!isReviewer(state.cloud.role))throw Error('Bài được lưu chờ duyệt; tài khoản này chưa có quyền chốt điểm.');if(!edit&&cloudDirty())throw Error('Đồng bộ cấu hình online trước khi quét hoặc lưu bài.');}
function applyCloudPermissions(){if(!state.cloud)return;let canManage=isManager(state.cloud.role),canReview=isReviewer(state.cloud.role),readOnly=state.cloud.role==='viewer'||state.cloud.closed||(page()==='review'&&current?.creator&&current.creator!==cloudUser?.id&&!canReview);for(let form of['configForm','keyForm'])if(!canManage||state.cloud.closed)$('#'+form)?.querySelectorAll('input,select,textarea,button').forEach(el=>el.disabled=true);for(let act of['add-code','go-import','load-setup'])if(!canManage||state.cloud.closed)$$('[data-action="'+act+'"]').forEach(el=>el.disabled=true);if(!canManage||state.cloud.closed)$('#excelFile')?.setAttribute('disabled','');if(readOnly)$$('[data-action="start-camera"],[data-action="capture"],[data-action="pick-image"],[data-action="save-draft"],#reviewForm input,#reviewForm button').forEach(el=>el.disabled=true);$('#examSelect')?.setAttribute('disabled','');$$('[data-action="preview-template"]').forEach(el=>el.disabled=false);if(!canReview||readOnly)$$('[data-action="save-final"],[data-action="regrade"]').forEach(el=>el.disabled=true);}

function list(){return records.filter(r=>r.examId===state.examId&&!r.demo&&(!state.cloud||(r.cloudAccount===cloudUser?.id&&(isManager(state.cloud.role)||withinAssignment(state.cloud.assignment,state.roster.find(s=>s.SBD===r.sbd),r.sbd)))));}
function page(){return location.hash.slice(1)||'home';}
function stopCamera(){cameraSession?.stop();cameraSession=null;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null;}clearInterval(autoTimer);autoTimer=null;document.body.classList.remove('camera-on');}
const intro=(title,desc,action='')=>`<div class="page-intro"><div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`;
