function stats(){let a=list(),done=a.filter(r=>r.status==='final'&&(!state.cloud||r.version===state.cfg.version)),ids=new Set(done.map(r=>r.sbd));return{all:a.length,done:done.length,pending:a.length-done.length,missing:state.roster.filter(r=>!ids.has(r.SBD)).length,avg:done.length?(done.reduce((s,r)=>s+r.result.total,0)/done.length).toFixed(2):'—'};}
function recordTable(a,short=false){if(!a.length)return empty('Chưa có bài chấm','Bắt đầu bằng cách tạo kỳ thi và quét phiếu đầu tiên.',button('go-scan','Quét bài đầu tiên','secondary','scan'));return `<div class="table-wrap"><table><thead><tr><th>HỌC SINH / SBD</th><th>MÃ ĐỀ</th><th>ĐIỂM</th><th>TRẠNG THÁI</th>${short?'':'<th>NGƯỜI CHẤM / LƯU TRỮ</th>'}<th></th></tr></thead><tbody>${a.map(r=>`<tr><td><b>${esc(r.name)}</b><br><span class="muted">${esc(r.sbd)}</span></td><td>${esc(r.code)}</td><td><b>${r.result?.total??'—'}</b></td><td><span class="tag ${r.status==='final'?'green':'orange'}">${r.status==='final'?'Đã chốt':'Cần duyệt'}</span>${r.version!==state.cfg.version?' <span class="tag orange">Đáp án đã đổi</span>':''}</td>${short?'':`<td>${esc(r.creatorName||'Trên thiết bị')}<br>${r.cloudError?'<span class="tag orange">Chưa đồng bộ</span><br>':''}<span class="small muted">${r.cloudExam?(r.cloudStamp===r.updated+'|'+r.status?'Online đã lưu':'Chờ đồng bộ'):r.drive?.marked?'Đã lưu Drive':r.drive?.error?'Lỗi tải Drive':'Chờ tải Drive'}</span></td>`}<td><button class="secondary" data-action="open-record" data-id="${esc(r.id)}">Xem</button></td></tr>`).join('')}</tbody></table></div>`;}
function home(){let s=stats(),ready=state.roster.length&&Object.values(state.keys).some(k=>completeKey(k,state.cfg));return `<section class="hero"><div class="hero-copy"><div class="kicker">TRỢ LÝ CHẤM THI CỦA THẦY CÔ</div><h1>Rõ từng ô tô.<br>Đúng từng điểm số.</h1><p>Quét phiếu bằng smartphone, chấm ba phần trắc nghiệm và lưu lại từng bài. Thầy cô luôn là người duyệt cuối cùng.</p><div class="actions">${button('go-scan','Bắt đầu quét bài','','scan')}${button('demo','Xem bài minh họa','secondary','arrow')}</div></div><div class="hero-art" aria-hidden="true"><div class="scan-frame"></div><div class="sheet-preview"><img src="./mau-bo.png" alt=""></div><div class="scan-line"></div><div class="floating-note"><span style="color:#368064">${icon('check')}</span><div><b>Ba phần. Một quy trình.</b><span>Quét · Kiểm tra · Lưu kết quả</span></div></div></div></section><section class="stat-grid">${[['Bài đã chốt',s.done,'Trong kỳ thi hiện tại','results'],['Cần duyệt',s.pending,'Kiểm tra trước khi chốt điểm','clock'],['Học sinh',state.roster.length,'Trong danh sách đã nhập','users'],['Điểm trung bình',s.avg,'Tính trên các bài đã chốt','stats']].map(([n,v,d,i])=>`<div class="stat"><span class="stat-label">${n}</span><span class="stat-icon">${icon(i)}</span><div class="stat-value">${v}</div><small>${d}</small></div>`).join('')}</section><div class="columns"><section class="card"><div class="card-head"><h2>Kỳ thi đang làm việc</h2><span class="tag ${ready?'green':'orange'}">${ready?'Sẵn sàng quét':'Đang thiết lập'}</span></div><h3>${esc(state.cfg.name)}</h3><p class="small">${templates[state.cfg.template].name} · ${state.cfg.mc} nhiều lựa chọn · ${state.cfg.tf} đúng–sai · ${state.cfg.sa} trả lời ngắn</p><div class="steps"><div class="step"><span class="step-number">01</span><div><h3>Thiết lập & nhập dữ liệu</h3><p>${state.roster.length} học sinh · ${Object.keys(state.keys).length} mã đề</p></div><a href="#exam">Thiết lập →</a></div><div class="step"><span class="step-number">02</span><div><h3>Quét phiếu & kiểm tra</h3><p>Nhận dạng SBD, mã đề và các ô trả lời.</p></div><a href="#scan">Mở camera →</a></div><div class="step"><span class="step-number">03</span><div><h3>Lưu ảnh & xuất điểm</h3><p>${token?'Drive đã kết nối':'Kết nối Google Drive để sao lưu ảnh.'}</p></div><a href="#drive">Kết nối →</a></div></div></section><section class="card"><div class="card-head"><h2>Quy ước chấm trên ảnh</h2>${icon('scan')}</div>${[['#149544','Xanh lục','Ô tô đúng; SBD và mã đề đọc rõ.'],['#dc3e42','Đỏ','Ô học sinh tô sai đáp án.'],['#247bd9','Xanh biển','Đáp án đúng ở câu / ý làm sai.'],['#d98620','Cam','Ô cần kiểm tra: mờ, tẩy xóa, tô kép.']].map(([c,n,d])=>`<div class="step"><span class="dot" style="background:${c};margin:9px 5px"></span><div><h3>${n}</h3><p>${d}</p></div></div>`).join('')}</section></div><section class="card"><div class="card-head"><h2>Bài chấm gần đây</h2><a class="small" href="#results">Xem tất cả →</a></div>${recordTable(list().slice().reverse().slice(0,4),true)}</section><div class="note small">Bản đầu cần kiểm chứng bằng phiếu tô thật trước khi dùng chấm chính thức. Bài minh họa được tách khỏi kết quả kỳ thi.</div>`;}
function field(label,name,value,type='number',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function settings(){let c=state.cfg;return `${intro('Kỳ thi & đáp án','Thiết lập một lần, dùng cho toàn bộ bài trong kỳ thi.',button('new-exam','Tạo kỳ thi mới','secondary','plus'))}<div class="tabs"><button class="secondary ${keyTab==='settings'?'active':''}" data-action="exam-tab" data-tab="settings">Cài đặt</button><button class="secondary ${keyTab==='students'?'active':''}" data-action="exam-tab" data-tab="students">Danh sách (${state.roster.length})</button><button class="secondary ${['mc','tf','sa'].includes(keyTab)?'active':''}" data-action="exam-tab" data-tab="mc">Đáp án (${Object.keys(state.keys).length})</button></div><div class="card" style="padding:15px 20px"><label for="examSelect">Chuyển kỳ thi</label><select id="examSelect"><option value="${esc(state.examId)}">${esc(state.cfg.name)} · Đang làm việc</option>${Object.values(state.archives||{}).filter(e=>e.examId!==state.examId).map(e=>`<option value="${esc(e.examId)}">${esc(e.cfg.name)}</option>`).join('')}</select></div>${keyTab==='settings'?configForm():keyTab==='students'?studentsView():keysView()}`;}
function configForm(){let c=state.cfg;return `<form id="configForm"><section class="card"><div class="card-head"><h2>Thông tin kỳ thi</h2><span class="tag">Phiên bản đáp án ${c.version}</span></div><fieldset ${c.locked?'disabled':''} style="border:0;padding:0;margin:0"><div class="form-grid">${field('Tên kỳ thi','name',c.name,'text','required maxlength="150"')}<div class="field"><label for="template">Mẫu phiếu</label><select name="template" id="template"><option value="bo" ${c.template==='bo'?'selected':''}>Bộ GD 2025 — CV1239</option><option value="qm" ${c.template==='qm'?'selected':''}>QM 2025 — CV1239</option></select></div></div><hr class="divider"><h3>Số câu & điểm từng phần</h3><p class="small">Chỉ chấm các câu từ 1 đến số câu đã chọn. Không tự quy đổi về thang 10.</p><div class="form-grid">${field('Phần I · Số câu (0–40)','mc',c.mc,'number','min="0" max="40" step="1" required')}${field('Điểm mỗi câu phần I','mcPoint',c.mcPoint,'number','min="0" step="0.001" required')}${field('Phần II · Số câu (0–8)','tf',c.tf,'number','min="0" max="8" step="1" required')}<div class="field"><label for="tfMode">Cách chấm đúng–sai</label><select name="tfMode" id="tfMode"><option value="table" ${c.tfMode==='table'?'selected':''}>Theo số ý đúng trong một câu</option><option value="each" ${c.tfMode==='each'?'selected':''}>Mỗi ý đúng có điểm riêng</option></select></div><div class="full"><label>Bảng điểm đúng–sai theo 0 / 1 / 2 / 3 / 4 ý đúng</label><div class="points">${c.tfTable.map((v,i)=>field(i+' ý đúng','tf'+i,v,'number','min="0" step="0.001" required')).join('')}</div></div>${field('Điểm mỗi ý đúng (chế độ từng ý)','tfPoint',c.tfPoint,'number','min="0" step="0.001" required')}${field('Phần III · Số câu (0–6)','sa',c.sa,'number','min="0" max="6" step="1" required')}${field('Điểm mỗi câu phần III','saPoint',c.saPoint,'number','min="0" step="0.001" required')}${field('Làm tròn tổng điểm (0–3 chữ số)','decimals',c.decimals,'number','min="0" max="3" step="1" required')}</div><hr class="divider"><h3>Nhận dạng & trả lời ngắn</h3><div class="form-grid">${field('Ngưỡng ô tô (0,30–0,85)','threshold',c.threshold,'number','min="0.3" max="0.85" step="0.01" required')}${field('Sai số tuyệt đối chấp nhận','tolerance',c.tolerance,'number','min="0" step="0.000001" required')}<div class="field"><label for="numeric">So sánh trả lời ngắn</label><select name="numeric" id="numeric"><option value="yes" ${c.numeric?'selected':''}>Theo giá trị số: 1,50 = 1,5</option><option value="no" ${!c.numeric?'selected':''}>Theo chuỗi ký tự: 1,50 khác 1,5</option></select></div></div><div class="note">Hai mẫu có 8 cột SBD và 4 cột mã đề. Bản này yêu cầu tô đủ các cột, kể cả số 0 đầu. Dấu chấm trong Excel được chuẩn hóa thành dấu phẩy.</div></fieldset><label class="checkline"><input type="checkbox" name="locked" ${c.locked?'checked':''}> Khóa cài đặt và đáp án để tránh sửa nhầm.</label><div class="actions"><button type="submit">Lưu cài đặt</button>${button('preview-template','Xem mẫu phiếu','secondary')}</div></section></form>`;}
function studentsView(){return `<section class="card"><div class="card-head"><div><h2>Nhập dữ liệu Excel / JSON</h2><p class="small" style="margin:3px 0">Chọn Excel để nhập dữ liệu hoặc JSON để nạp kỳ thi đã chuẩn bị.</p></div><div class="actions">${button('load-setup','Nạp kỳ thi đã chuẩn bị','secondary')}${button('download-template','Tải Excel mẫu','secondary','upload')}</div></div><input id="examSetupFile" type="file" accept=".json" class="hidden"><div class="upload">${icon('upload')}<h3>Chọn file Excel hoặc JSON</h3><p>.xlsx · .xls · .json — JSON đã chuẩn bị sẽ nạp cả danh sách và đáp án.</p><input type="file" id="excelFile" accept="${IMPORT_ACCEPT}" aria-label="Chọn file Excel hoặc JSON"></div><div class="note">Sheet <b>HocSinh</b>: SBD, HoTen, Lop; có thể thêm cột Phong hoặc PhongThi để phân công theo phòng. Sheet <b>DapAn</b>: MaDe, Phan, Cau, Y, DapAn. Cũng nhận bảng <b>MaDe, Phan1, Phan2, Phan3</b> với mỗi mã đề một dòng; phần III ngăn đáp số bằng dấu chấm phẩy. SBD và mã đề ngắn được thêm số 0 ở đầu cho đủ 8 / 4 chữ số.</div></section><section class="card"><div class="card-head"><h2>Danh sách học sinh</h2><span class="tag">${state.roster.length} học sinh</span></div>${state.roster.length?`<div class="table-wrap"><table><thead><tr><th>SBD</th><th>HỌ TÊN</th><th>LỚP</th><th>PHÒNG</th></tr></thead><tbody>${state.roster.map(r=>`<tr><td>${esc(r.SBD)}</td><td>${esc(r.HoTen)}</td><td>${esc(r.Lop)}</td><td>${esc(r.Phong||'')}</td></tr>`).join('')}</tbody></table></div>`:empty('Chưa có danh sách','Tải file mẫu, điền thông tin rồi nhập lại vào web.')}</section>`;}
function keysView(){let codes=Object.keys(state.keys).sort();if(!codes.includes(activeCode))activeCode=codes[0]||'';let key=state.keys[activeCode];return `<section class="card"><div class="card-head"><div><h2>Đáp án theo mã đề</h2><p class="small" style="margin:4px 0">${state.cfg.locked?'Đáp án đang khóa. Mở khóa trong Cài đặt để sửa.':'Nhập Excel hoặc nhập trực tiếp. Mỗi lần lưu tạo phiên bản mới.'}</p></div>${button('download-template','Excel mẫu','secondary')}</div><div class="actions"><select id="codeSelect" aria-label="Chọn mã đề" style="max-width:180px">${codes.length?codes.map(c=>`<option ${c===activeCode?'selected':''}>${esc(c)}</option>`).join(''):'<option>Chưa có mã đề</option>'}</select>${button('add-code','Thêm mã đề','secondary','plus')}${button('go-import','Nhập Excel','ghost','upload')}</div>${key?`<hr class="divider"><div class="badges"><span class="tag ${completeKey(key,state.cfg)?'green':'orange'}">${completeKey(key,state.cfg)?'Đáp án đầy đủ':'Cần nhập đủ đáp án'}</span><span class="tag">Mã ${esc(activeCode)}</span></div><form id="keyForm"><fieldset ${state.cfg.locked?'disabled':''} style="border:0;padding:0"><h3 style="margin-top:20px">Phần I · Nhiều lựa chọn</h3><div class="answer-grid">${Array.from({length:state.cfg.mc},(_,q)=>`<div class="answer-cell"><label for="k_mc_${q}">${q+1}</label><select id="k_mc_${q}" name="mc_${q}" required><option value="">—</option>${'ABCD'.split('').map(v=>`<option ${key.mc[q]===v?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}</div><h3 style="margin-top:22px">Phần II · Đúng–sai</h3><div class="form-grid">${Array.from({length:state.cfg.tf},(_,q)=>`<div class="field"><label for="k_tf_${q}">Câu ${q+1} · a, b, c, d</label><input id="k_tf_${q}" name="tf_${q}" value="${esc(key.tf[q]?.join('')||'')}" placeholder="ĐSĐS" required pattern="[ĐSđsDd]{4}" maxlength="4"></div>`).join('')}</div><h3 style="margin-top:22px">Phần III · Trả lời ngắn</h3><div class="answer-grid">${Array.from({length:state.cfg.sa},(_,q)=>`<div class="answer-cell"><label for="k_sa_${q}">${q+1}</label><input id="k_sa_${q}" name="sa_${q}" value="${esc(key.sa[q]??'')}" required maxlength="4" placeholder="-1,5"></div>`).join('')}</div><p class="small" style="margin-top:12px">Tối đa 4 ký tự; dấu trừ ở cột đầu, dấu phẩy ở cột 2 hoặc 3 theo mẫu phiếu.</p><button style="margin-top:15px" type="submit">Lưu đáp án mã ${esc(activeCode)}</button></fieldset></form>`:empty('Chưa có đáp án','Thêm mã đề hoặc nhập đáp án từ Excel.')}</section>`;}
function scanView(){return `${intro('Quét bài làm','Đặt phiếu phẳng, đủ bốn góc và tránh bóng đổ.',button('demo','Thử bài minh họa','secondary'))}<div class="scan-layout"><div><div class="camera-stage"><video id="video" playsinline muted class="hidden"></video><div id="cameraPlaceholder" class="camera-placeholder">${icon('camera')}<h2>Sẵn sàng cho bài đầu tiên</h2><p>Dùng camera sau hoặc chọn ảnh phiếu đã chụp trên điện thoại.</p>${button('start-camera','Mở camera','','camera')}</div><canvas class="camera-overlay hidden" id="cameraOverlay" aria-hidden="true"></canvas></div><div class="camera-feedback-row"><span class="paper-badge">A4</span><div class="camera-feedback hidden" id="cameraLabel" role="status" aria-live="polite">Đưa đủ bốn ô góc vào khung</div></div><div class="camera-bar">${button('capture','Chụp ngay','','scan')}${button('pick-image','Chọn ảnh','secondary','upload')}${button('stop-camera','Tắt camera','secondary')}</div><input class="hidden" id="photoFile" type="file" accept="image/*"><label class="checkline"><input id="autoCapture" type="checkbox" ${cameraAuto?'checked':''}> Tự chụp khi đủ 4 góc và giữ yên.</label><div class="batch-settings"><label class="checkline"><input id="batchMode" type="checkbox" ${batchMode?'checked':''}> Quét nhiều phiếu liên tục · Tự lưu chờ duyệt</label><label for="batchDelay">Thời gian giữ yên</label> <select id="batchDelay"><option value="3" ${batchDelay===3?'selected':''}>3 giây</option><option value="5" ${batchDelay===5?'selected':''}>5 giây</option></select><p class="small" id="batchProgress">${batchMode?'Đã lưu '+batchCount+' phiếu trong lượt này. Lấy phiếu cũ ra khỏi khung sau mỗi lần chụp.':'Bật để giữ camera mở và duyệt các bài sau khi quét xong.'}</p><a href="#results">Kết thúc & xem hàng chờ duyệt →</a></div><div class="note warn" id="scanStatus">Chưa mở camera. Chế độ liên tục tự lưu ảnh và kết quả tạm để duyệt sau.</div></div><div><section class="card"><div class="card-head"><h2>Cấu hình đang dùng</h2><a class="small" href="#exam">Thay đổi →</a></div><h3>${esc(state.cfg.name)}</h3><p class="small">${templates[state.cfg.template].name}</p><div class="step"><span class="step-number">I</span><div><h3>${state.cfg.mc} câu nhiều lựa chọn</h3><p>${state.cfg.mcPoint} điểm / câu</p></div></div><div class="step"><span class="step-number">II</span><div><h3>${state.cfg.tf} câu đúng–sai</h3><p>${state.cfg.tfMode==='table'?'Theo số ý đúng':'Theo từng ý'}</p></div></div><div class="step"><span class="step-number">III</span><div><h3>${state.cfg.sa} câu trả lời ngắn</h3><p>${state.cfg.saPoint} điểm / câu</p></div></div><div class="note ${!state.roster.length||!Object.values(state.keys).some(k=>completeKey(k,state.cfg))?'warn':''}">${state.roster.length} học sinh · ${Object.keys(state.keys).length} mã đề<br>${!state.roster.length?'Cần nhập danh sách trước khi chốt bài.':'SBD phải khớp danh sách đã nhập.'}</div></section><section class="card"><h3>Mẹo để nhận dạng tốt</h3><p class="small">In đúng tỉ lệ, không cắt mất dấu định vị. Dùng nền bàn tối, ánh sáng đều. Giữ điện thoại song song với mặt giấy.</p><a href="#help" class="small">Xem cách xử lý ô tô mờ →</a></section></div></div>`;}
function reviewView(){if(!current)return empty('Chưa có bài để duyệt','Quét phiếu hoặc mở bài đã lưu.',button('go-scan','Quét bài'));let c=current,key=c.demo?c.demoKey:c.recordId&&c.key?c.key:state.keys[c.code],g=completeKey(key,c.cfg||state.cfg)?grade(c.answers,key,c.cfg||state.cfg):null,student=c.demo?{HoTen:'Nguyễn Minh An · Minh họa',Lop:'12A1'}:state.roster.find(r=>r.SBD===c.sbd);c.result=g;let warnings=c.warnings||[];return `${intro(c.demo?'Bài minh họa':'Kiểm tra bài làm',c.demo?'Phiếu được tô bằng chương trình để kiểm tra luồng; không tính vào kết quả kỳ thi.':'Đối chiếu ảnh và câu trả lời trước khi chốt điểm.',button('go-scan','Quét bài tiếp','secondary','scan'))}<div class="scan-layout"><div><div class="review-image"><canvas id="reviewCanvas" class="review-canvas"></canvas></div><div class="legend"><span><i class="dot" style="background:#149544"></i>Đúng / SBD / mã đề</span><span><i class="dot" style="background:#dc3e42"></i>Sai</span><span><i class="dot" style="background:#247bd9"></i>Đáp án</span><span><i class="dot" style="background:#d98620"></i>Cần kiểm tra</span></div><div class="actions">${button('download-marked','Tải ảnh chấm','secondary')}${button('download-original','Tải ảnh gốc','ghost')}${c.original&&!c.recordId?button('rotate-image','Xoay ảnh 90°','ghost'):''}</div><p class="small muted">${c.edits?.length?'Đã sửa nhận dạng: vòng màu vẫn chỉ vị trí ô tô gốc, dữ liệu sửa được lưu trong lịch sử.':'Có thể phóng to ảnh bằng cách mở ảnh chấm sau khi tải.'}</p></div><section class="card review-panel"><div class="review-heading"><div><h2>${esc(student?.HoTen||'Chưa khớp học sinh')}</h2><span class="small muted">${esc(student?.Lop||'Kiểm tra lại SBD')}</span></div><div><b>${g?.total??'—'}</b><span class="small muted"> điểm</span></div></div><div class="badges" style="margin:14px 0"><span class="tag ${c.quality?.good?'green':'orange'}">${c.quality?.good?'Căn phiếu đạt kiểm tra':'Cần kiểm tra căn phiếu'}</span><span class="tag ${warnings.length?'orange':'green'}">${warnings.length} cảnh báo nhận dạng</span></div>${warnings.length?`<div class="note warn"><b>Cần đối chiếu trên ảnh</b><br>${(c.groups||[]).filter(x=>x.uncertain&&(x.part==='sbd'||x.part==='code'||x.q<(c.cfg||state.cfg)[x.part])).map(x=>{let label=x.part==='sbd'?'SBD · cột '+(x.q+1):x.part==='code'?'Mã đề · cột '+(x.q+1):({mc:'Phần I',tf:'Phần II',sa:'Phần III'}[x.part]+' · câu '+(x.q+1)+(x.part==='tf'?'abcd'[x.sub]:''));return esc(label)+': '+esc(x.tentative?'gợi ý '+x.value+' — tô mờ / chưa kín, cần đối chiếu':x.faint?.length?'vết tô / tẩy mờ ở '+x.faint.join(', '):x.marked.length>1?'tô nhiều ô':'độ đậm sát ngưỡng, cần kiểm tra');}).join('<br>')}</div>`:''}${g?`<div class="note">Phần I: <b>${g.parts[0]}</b> · Phần II: <b>${g.parts[1]}</b> · Phần III: <b>${g.parts[2]}</b></div>`:'<div class="note error">Mã đề chưa có đáp án đầy đủ. Chưa thể tính hoặc chốt điểm.</div>'}<form id="reviewForm"><div class="form-grid">${field('Số báo danh','sbd',c.sbd,'text','inputmode="numeric" pattern="[0-9]{8}" maxlength="8" required')}${field('Mã đề','code',c.code,'text','inputmode="numeric" pattern="[0-9]{4}" maxlength="4" required')}</div><h3 style="margin-top:20px">I · Nhiều lựa chọn</h3><div class="answer-grid">${Array.from({length:(c.cfg||state.cfg).mc},(_,q)=>`<div class="answer-cell ${warnings.includes('mc'+q)?'flagged':''}"><label for="r_mc_${q}">${q+1}</label><input aria-label="Phần I câu ${q+1}" id="r_mc_${q}" name="mc_${q}" value="${esc(c.answers.mc[q]??'')}" placeholder="Trống" maxlength="7"></div>`).join('')}</div><h3 style="margin-top:20px">II · Đúng–sai</h3><div class="form-grid">${Array.from({length:(c.cfg||state.cfg).tf},(_,q)=>`<div class="field"><label>Câu ${q+1} · a / b / c / d</label><div class="points" style="grid-template-columns:repeat(4,1fr)">${Array.from({length:4},(_,j)=>`<input aria-label="Phần II câu ${q+1} ý ${'abcd'[j]}" name="tf_${q}_${j}" value="${esc(c.answers.tf[q]?.[j]??'')}" placeholder="—" maxlength="3" style="${warnings.includes('tf'+q+'_'+j)?'border-color:#d99d50':''}">`).join('')}</div></div>`).join('')}</div><h3 style="margin-top:20px">III · Trả lời ngắn</h3><div class="answer-grid">${Array.from({length:(c.cfg||state.cfg).sa},(_,q)=>`<div class="answer-cell ${warnings.some(w=>w.startsWith('sa'+q))?'flagged':''}"><label>${q+1}</label><input aria-label="Phần III câu ${q+1}" name="sa_${q}" value="${esc(c.answers.sa[q]??'')}" placeholder="Trống" maxlength="12"></div>`).join('')}</div><p class="small muted" style="margin-top:12px">A–D; Đ/S; đáp số số học. Để trống nếu bỏ câu; dùng dấu | nếu tô kép.</p><button class="secondary" type="submit">Cập nhật nhận dạng & tính lại</button></form><label class="checkline"><input type="checkbox" id="reviewAccepted" ${c.accepted?'checked':''}> Tôi đã đối chiếu ảnh, các ô cảnh báo, SBD và mã đề. Các ô tô kép hoặc trống được xử lý đúng quy tắc kỳ thi.</label><div class="actions">${button('save-final','Chốt điểm & lưu bài','','check')}${button('save-draft','Lưu chờ duyệt','secondary')}</div><div class="note small">${c.demo?'Bài minh họa chỉ để thử; không được lưu vào kết quả thật.':'Lưu trên thiết bị trước. Chỉ báo “Đã lưu Drive” khi tải ảnh thành công.'}</div>${c.edits?.length?`<div class="history"><b>Lịch sử sửa nhận dạng</b>${c.edits.slice(-8).map(e=>`<div>${esc(e.text)} · ${new Date(e.at).toLocaleString('vi-VN')}</div>`).join('')}</div>`:''}</section></div>`;}
function filteredRecords(){return list().filter(r=>(r.sbd+' '+r.name+' '+r.code+' '+r.className).toLocaleLowerCase().includes(resultQuery.toLocaleLowerCase())&&(!resultClass||r.className===resultClass)&&(!resultRoom||state.roster.find(s=>s.SBD===r.sbd)?.Phong===resultRoom)&&(!resultTeacher||(r.creatorName||'Trên thiết bị')===resultTeacher)&&(!resultStatus||(resultStatus==='Đã chốt'?r.status==='final'&&r.version===state.cfg.version:r.status!=='final'||r.version!==state.cfg.version)));}
function resultsView(){let a=filteredRecords().slice().reverse(),s=stats();return `${intro('Bài đã chấm',`${s.done} bài đã chốt · ${s.pending} bài chờ duyệt · ${s.missing} học sinh chưa có điểm`,button('export-results','Xuất Excel','secondary','upload'))}<section class="card"><div class="card-head"><input id="resultSearch" class="search" placeholder="Tìm họ tên, SBD, mã đề…" aria-label="Tìm bài" value="${esc(resultQuery)}"><div class="actions">${button('regrade','Chấm lại theo đáp án mới','secondary')}${button('backup','Sao lưu dữ liệu','ghost')}</div></div><div class="form-grid result-filters">${[['resultClass','Lớp',resultClass,[...new Set(list().map(r=>r.className).filter(Boolean))]],['resultRoom','Phòng thi',resultRoom,[...new Set(state.roster.map(r=>r.Phong).filter(Boolean))]],['resultTeacher','Giáo viên',resultTeacher,[...new Set(list().map(r=>r.creatorName||'Trên thiết bị'))]],['resultStatus','Trạng thái',resultStatus,['Đã chốt','Chờ duyệt']]].map(([id,label,value,options])=>`<div class="field"><label for="${id}">${label}</label><select id="${id}"><option value="">Tất cả</option>${options.sort().map(o=>`<option value="${esc(o)}" ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`).join('')}</div><p class="small">Đang hiển thị ${a.length} bài. Excel xuất theo bộ lọc hiện tại.</p>${recordTable(a)}</section><section class="card"><h3>Học sinh chưa có bài đã chốt</h3><p class="small muted">${state.roster.filter(s=>!list().some(r=>r.status==='final'&&r.sbd===s.SBD)).map(r=>esc(r.SBD+' — '+r.HoTen)).join(' · ')||'Không có học sinh thiếu bài trong danh sách hiện tại.'}</p><div class="note">Sao lưu dữ liệu tải toàn bộ kỳ thi và ảnh về một tệp JSON. Dùng chức năng Khôi phục trong Hướng dẫn để chuyển sang thiết bị khác.</div></section>`;}
function statsView(){let a=list().filter(r=>r.status==='final'&&r.result&&(!state.cloud||r.version===state.cfg.version)),s=stats(),max=state.cfg.mc*state.cfg.mcPoint+state.cfg.sa*state.cfg.saPoint+state.cfg.tf*(state.cfg.tfMode==='table'?Math.max(...state.cfg.tfTable):4*state.cfg.tfPoint);return `${intro('Thống kê kỳ thi','Chỉ tính các bài đã chốt; bài minh họa không được đưa vào thống kê.')}<div class="stat-grid">${[['Bài đã chốt',s.done],['Điểm trung bình',s.avg],['Điểm cao nhất',a.length?Math.max(...a.map(r=>r.result.total)):'—'],['Học sinh chưa có điểm',s.missing]].map(([n,v])=>`<div class="stat"><span class="stat-label">${n}</span><div class="stat-value">${v}</div></div>`).join('')}</div><div class="columns"><section class="card"><h2>Phân bố điểm</h2><p class="small">Thang điểm tối đa theo cài đặt: ${max.toFixed(2)}</p>${Array.from({length:5},(_,i)=>{let lo=max*i/5,hi=max*(i+1)/5,n=a.filter(r=>r.result.total>=lo&&(i===4?r.result.total<=hi:r.result.total<hi)).length;return `<div class="bar-row"><span>${lo.toFixed(1)}–${hi.toFixed(1)}</span><span class="bar"><i style="width:${a.length?n/a.length*100:0}%"></i></span><b>${n}</b></div>`;}).join('')}</section><section class="card"><h2>Tỷ lệ đúng theo câu / ý</h2>${a.length?`<div class="table-wrap"><table><thead><tr><th>CÂU / Ý</th><th>ĐÚNG</th><th>TỶ LỆ</th></tr></thead><tbody>${(a[0].result.detail||[]).map(d=>{let n=a.filter(r=>r.result.detail.find(x=>x.part===d.part&&x.q===d.q&&x.sub===d.sub)?.ok).length;return `<tr><td>${{mc:'I',tf:'II',sa:'III'}[d.part]} · ${d.q+1}${d.sub!==undefined?'abcd'[d.sub]:''}</td><td>${n}/${a.length}</td><td>${(n/a.length*100).toFixed(0)}%</td></tr>`;}).join('')}</tbody></table></div>`:empty('Chưa có dữ liệu thống kê','Chốt bài đầu tiên để xem phân bố điểm.')}</section></div>`;}
function driveView(){let d=state.drive;return `${intro('Google Drive','Lưu ảnh gốc và ảnh chấm vào thư mục riêng của thầy cô.')}<div class="columns"><section class="card"><div class="card-head"><h2>Kết nối tài khoản Google</h2><span class="tag ${token?'green':'orange'}">${token?'Đã kết nối trong phiên này':'Chưa kết nối'}</span></div><p class="small">Bản web này dùng OAuth của Google. Cần một OAuth Client ID dành cho ứng dụng web, với địa chỉ web này được thêm vào Authorized JavaScript origins.</p><form id="driveForm"><div class="field"><label for="clientId">Google OAuth Client ID</label><input id="clientId" name="clientId" value="${esc(d.clientId)}" placeholder="….apps.googleusercontent.com" required><small>Đây là mã công khai của ứng dụng, không phải mật khẩu hay Client Secret.</small></div><div class="field" style="margin-top:16px"><label for="folderName">Tên thư mục ảnh trên Drive</label><input id="folderName" name="folderName" value="${esc(d.folderName)}" required maxlength="120"></div><button style="margin-top:18px" type="submit">Lưu cấu hình kết nối</button></form><hr class="divider"><div class="actions">${button('connect-drive','Đăng nhập Google & cấp quyền','','drive')}${token?button('disconnect-drive','Ngắt phiên kết nối','secondary'):''}</div><div class="note">Ứng dụng tạo thư mục của riêng mình trong Drive. Không cần cấp quyền toàn bộ Drive. Thầy cô sẽ chọn tài khoản trong cửa sổ Google.</div></section><section class="card"><h2>Hàng chờ tải ảnh</h2><p class="small">${list().filter(r=>!r.drive?.marked||!r.drive?.original).length} bài chưa lưu đủ hai ảnh trên Google Drive.</p>${button('sync-drive','Tải các bài đang chờ lên Drive','','upload')}<div class="status-panel"><h3>Ảnh được lưu gồm</h3><p>01 · Ảnh chụp gốc</p><p>02 · Ảnh đã căn chỉnh, khoanh màu và ghi điểm</p><p>Tên tệp có SBD, mã đề và mã bài để tránh ghi đè.</p></div>${d.folderId?`<p class="small" style="margin-top:15px"><a href="https://drive.google.com/drive/folders/${encodeURIComponent(d.folderId)}" target="_blank" rel="noopener">Mở thư mục trên Google Drive ↗</a></p>`:''}<div class="note warn">Chấm và lưu trên thiết bị vẫn dùng được khi chưa kết nối. Không xóa dữ liệu trình duyệt trước khi sao lưu.</div></section></div><section class="card"><h3>Cấu hình Google Cloud cần thực hiện một lần</h3><ol class="small muted"><li>Tạo dự án Google Cloud, bật Google Drive API.</li><li>Cấu hình màn hình đồng ý OAuth; nếu ứng dụng ở chế độ thử nghiệm, thêm tài khoản thầy cô vào Test users.</li><li>Tạo OAuth Client ID loại Web application; thêm origin <span class="code">${esc(location.origin)}</span>.</li><li>Dán Client ID vào ô trên, lưu rồi đăng nhập Google.</li></ol><p class="small">Quyền yêu cầu: <span class="code">https://www.googleapis.com/auth/drive.file</span>. Token chỉ giữ trong bộ nhớ của phiên mở web.</p></section>`;}
function helpView(){return `${intro('Hướng dẫn sử dụng','Bắt đầu với một kỳ thi thử và vài phiếu tô thật.')}<section class="card"><h2>Chuẩn bị trong 5 bước</h2><ol><li>Vào <a href="#exam">Kỳ thi & đáp án</a>, chọn đúng mẫu, số câu và thang điểm.</li><li>Tải Excel mẫu, điền danh sách cùng đáp án. Dùng 8 chữ số SBD và 4 chữ số mã đề.</li><li>Kiểm tra đáp án từng mã; khóa cài đặt khi đã đúng.</li><li>Mở <a href="#scan">Quét bài</a>, chụp đủ bốn góc. Chọn định vị tay nếu tự động chưa tìm đủ góc.</li><li>Duyệt ảnh và cảnh báo, chốt bài rồi xuất Excel hoặc tải lên Drive.</li></ol><div class="note warn">Nhận dạng bằng ảnh cần được thử trên phiếu thật. Chương trình chưa được kiểm chứng độ chính xác trên máy in, bút chì và camera của thầy cô.</div></section><div class="columns"><section class="card"><h2>Quy tắc chấm</h2><p class="small">Phần I: chỉ đúng khi chọn duy nhất đáp án chuẩn. Phần II: mỗi ý Đ/S được so với đáp án, sau đó tính điểm theo cấu hình. Phần III: ghép ô từ trái sang phải, bỏ các cột trống cuối; sai vị trí dấu hoặc có khoảng trống giữa chuỗi sẽ cảnh báo.</p><p class="small">Ô trống và tô kép không có điểm. Mỗi bài phải được người dùng duyệt trước khi chốt. Ảnh khoanh chỉ ô tô gốc; mọi sửa nhận dạng được lưu riêng trong lịch sử.</p></section><section class="card"><h2>Lưu trữ & khôi phục</h2><p class="small">Dữ liệu nằm trong trình duyệt trên thiết bị đang dùng. Mở web trên máy khác chưa tự có danh sách và ảnh. Dùng tệp sao lưu để chuyển đầy đủ dữ liệu.</p><div class="actions">${button('backup','Tải bản sao lưu','secondary')}${button('restore','Khôi phục tệp','secondary')}</div><input type="file" accept=".json" id="restoreFile" class="hidden"><p class="small" style="margin-top:15px">Khi khôi phục, bài khác mã được giữ lại; cấu hình kỳ thi hiện tại chuyển sang kỳ thi trong tệp.</p></section></div><section class="card"><h2>Dùng trên điện thoại</h2><p class="small">Mở địa chỉ web bằng trình duyệt, đăng nhập tài khoản có quyền truy cập. Có thể dùng “Thêm vào màn hình chính” nếu trình duyệt hỗ trợ. Camera cần được cấp quyền. Khi mạng yếu, ưu tiên lưu bài trên thiết bị và tải lên Drive sau.</p><p class="small">Bản hiện tại chưa cam kết hoạt động khi mở lại hoàn toàn không có mạng; không có chức năng chấm chữ viết tay hoặc tự luận.</p></section>`;}
function render(){stopCamera();$('#pageTitle').textContent=navs.find(([r])=>r===page())?.[1]||(page()==='review'?'Duyệt bài làm':'Tổng quan');$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.route===page()||(page()==='review'&&a.dataset.route==='scan')));$('#driveTag').textContent=token?'Drive đã kết nối':'Drive chưa kết nối';$('#driveTag').className='tag '+(token?'green':'');$('#app').innerHTML=cloudBanner()+({home,exam:settings,scan:scanView,review:reviewView,results:resultsView,stats:statsView,drive:driveView,help:helpView}[page()]||home)();if(page()==='review'&&current)paintReview();applyCloudPermissions();syncBadge();let foot=$('.sidebar-foot small');if(foot)foot.textContent=state.cloud?'Ảnh & điểm đồng bộ theo quyền của kỳ thi.':'Ảnh & dữ liệu lưu trên thiết bị. Kết nối Drive để sao lưu.';window.scrollTo(0,0);if(page()==='scan'&&resumeCamera){resumeCamera=false;startCamera().catch(e=>toast(e.message));}}
function paintReview(){let t=templates[current.cfg?.template||state.cfg.template],out=annotate(current.upright,t,current.groups,current.result,{sbd:current.sbd,code:current.code,name:current.demo?'Nguyễn Minh An':state.roster.find(s=>s.SBD===current.sbd)?.HoTen,demo:current.demo},current.edits);current.annotated=out;let c=$('#reviewCanvas');if(c){c.width=out.width;c.height=out.height;c.getContext('2d').drawImage(out,0,0);}}
function saveFile(blob,name){let a=document.createElement('a'),u=URL.createObjectURL(blob);a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}
function downloadBook(sheets,name){let wb=XLSX.utils.book_new();for(let[n,rows]of sheets){let ws=XLSX.utils.json_to_sheet(rows);for(let addr in ws)if(!addr.startsWith('!')&&(addr.startsWith('A')||addr.startsWith('B')))ws[addr].z='@';ws['!cols']=[{wch:18},{wch:28},{wch:17},{wch:16},{wch:16},{wch:22}];XLSX.utils.book_append_sheet(wb,ws,n);}saveFile(new Blob([XLSX.write(wb,{bookType:'xlsx',type:'array'})],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),name);toast('Đã tạo tệp Excel để tải về.');}
function sampleWorkbook(){let answers=[];for(let q=0;q<state.cfg.mc;q++)answers.push({MaDe:'1201',Phan:1,Cau:q+1,Y:'',DapAn:'ABCD'[q%4]});for(let q=0;q<state.cfg.tf;q++)for(let j=0;j<4;j++)answers.push({MaDe:'1201',Phan:2,Cau:q+1,Y:'abcd'[j],DapAn:j%2?'S':'Đ'});for(let q=0;q<state.cfg.sa;q++)answers.push({MaDe:'1201',Phan:3,Cau:q+1,Y:'',DapAn:['-1,5','2','0,25','12','3,5','-2'][q]});downloadBook([['HocSinh',[{SBD:'00123456',HoTen:'Nguyễn Minh An',Lop:'12A1'},{SBD:'00123457',HoTen:'Trần Ngọc Hà',Lop:'12A1'}]],['DapAn',answers],['HuongDan',[{NoiDung:'Dữ liệu mẫu: thay bằng danh sách và đáp án thật trước khi chấm.'},{NoiDung:'Phan: 1, 2 hoặc 3. Y: a, b, c, d cho phần 2; Đ/S hoặc D/S.'},{NoiDung:'Giữ SBD và MaDe dạng Text. Nhập đủ đáp án theo cấu hình kỳ thi.'}]]],'Mau_nhap_ChamThi.xlsx');}
function cleanRow(row){return Object.fromEntries(Object.entries(row).map(([k,v])=>[k.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').replace(/[^a-z0-9]/gi,'').toLowerCase(),String(v??'').trim()]));}
const tfValue=s=>({D:'Đ',Đ:'Đ',S:'S',TRUE:'Đ',FALSE:'S',DUNG:'Đ',SAI:'S'}[String(s).toUpperCase()]||'');
function shortValid(v){let s=String(v).replace('.',',');return s.length<=4&&/^-?\d+(,\d+)?$/.test(s)&&(!s.includes(',')||[1,2].includes(s.indexOf(',')));}
async function applyWorkbook(wb,options={}){if(state.cfg.locked)throw Error('Cài đặt và đáp án đang khóa. Mở khóa trước khi nhập.');let{roster,keys}=parseWorkbook(wb,state.cfg,XLSX,options),next=structuredClone(state);if(roster)next.roster=roster;next.keys={...next.keys,...keys};next.cfg.version++;await put('meta',next);state=next;pendingWorkbook=null;$('#modal').close();toast(`Đã nhập ${roster?.length??0} học sinh và ${Object.keys(keys).length} mã đề.`);render();}
async function importExcel(file){if(state.cfg.locked)throw Error('Cài đặt và đáp án đang khóa. Mở khóa trước khi nhập.');let wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellText:true});let norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[đĐ]/g,'d').replace(/[^a-z0-9]/gi,'').toLowerCase();let candidates=wb.SheetNames.filter(n=>{let h=(XLSX.utils.sheet_to_json(wb.Sheets[n],{header:1,range:'A1:Z1',raw:false,defval:''})[0]||[]).map(norm);return h.includes('sbd')&&h.includes('hoten');});if(candidates.length){pendingWorkbook=wb;let preferred=candidates.includes('Sheet12')?'Sheet12':candidates.find(n=>n.toLowerCase()==='hocsinh')||candidates[0];showModal(`<h2>Chọn sheet danh sách học sinh</h2><p class="small">Chỉ nhập SBD, họ tên và lớp từ sheet đã chọn. Các sheet danh sách khác được bỏ qua.</p><form id="importSheetForm"><label for="rosterSheet">Sheet danh sách</label><select id="rosterSheet" name="rosterSheet">${candidates.map(n=>`<option value="${esc(n)}" ${n===preferred?'selected':''}>${esc(n)}</option>`).join('')}<option value="">Chỉ nhập đáp án</option></select><button type="submit" style="margin:16px 0">Nhập sheet đã chọn</button></form>`);return;}await applyWorkbook(wb);}

async function startCamera(){cloudGuard();if(!navigator.mediaDevices?.getUserMedia)throw Error('Trình duyệt chưa hỗ trợ camera hoặc chưa ở kết nối HTTPS. Dùng Chọn ảnh có sẵn.');stopCamera();stream=await navigator.mediaDevices.getUserMedia({audio:false,video:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:2560},aspectRatio:{ideal:A4_RATIO}}});let v=$('#video');if(!v){stopCamera();return;}v.srcObject=stream;v.classList.remove('hidden');await v.play().catch(e=>{stopCamera();throw e;});let track=stream.getVideoTracks()[0];try{let caps=track.getCapabilities?.();if(caps?.focusMode?.includes('continuous'))await track.applyConstraints({advanced:[{focusMode:'continuous'}]});}catch{}if(page()!=='scan'||!document.contains(v)){stopCamera();return;}document.body.classList.add('camera-on');$('#cameraPlaceholder').classList.add('hidden');$('#cameraOverlay').classList.remove('hidden');$('#cameraLabel').classList.remove('hidden');$('#scanStatus').textContent='Mẫu '+templates[state.cfg.template].name+' · Giữ phẳng phiếu và đủ bốn ô neo ngoài cùng.';cameraSession=createCameraScanner({source:v,overlay:$('#cameraOverlay'),template:templates[state.cfg.template],label:$('#cameraLabel'),isAutoEnabled:()=>cameraAuto,getCaptureDelay:()=>batchMode?batchDelay*1000:400,isContinuous:()=>batchMode,isBusy:()=>busy||$('#modal').open,onStatus:message=>{if($('#scanStatus'))$('#scanStatus').textContent=message;},onCapture:options=>capture({...options,automatic:true})});window.scrollTo(0,0);}
async function capture(options={}){let v=$('#video');if(!stream||!v?.videoWidth)throw Error('Mở camera hoặc chọn ảnh trước.');let c=cameraFrame(v,2560),live=options.liveAnchors?{anchors:options.liveAnchors,width:options.liveWidth,height:options.liveHeight}:cameraSession?.getLatest(),anchors=live?.anchors?.map(([x,y])=>[x/live.width*c.width,y/live.height*c.height]),refined=anchors?refineTrackedCorners(c.getContext('2d',{willReadFrequently:true}).getImageData(0,0,c.width,c.height).data,c.width,c.height,anchors,templates[state.cfg.template]):null;if(options.automatic&&(!refined||refined.clipped)){if($('#scanStatus'))$('#scanStatus').textContent='Bốn góc đã dịch chuyển khi chụp. Đưa đủ các ô neo vào hình và giữ máy yên.';return false;}anchors=refined?.anchors||anchors;return await scanBlob(await toBlob(c),anchors,{automatic:!!options.automatic});}

