async function ensureFolder(){let d=state.drive;if(d.folderId){try{let f=await driveFetch('drive/v3/files/'+encodeURIComponent(d.folderId)+'?fields=id,trashed');if(!f.trashed)return f.id;}catch(e){throw Error('Không truy cập được thư mục Drive đã lưu. Kiểm tra tài khoản và cấu hình.');}}let q="mimeType='application/vnd.google-apps.folder' and trashed=false and appProperties has { key='chamthiFolder' and value='v1' } and name='"+d.folderName.replace(/\\/g,'\\\\').replace(/'/g,"\\'")+"'",r=await driveFetch('drive/v3/files?q='+encodeURIComponent(q)+'&fields=files(id,name)');let id=r.files?.[0]?.id;if(!id){let f=await driveFetch('drive/v3/files?fields=id',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:d.folderName,mimeType:'application/vnd.google-apps.folder',appProperties:{chamthiFolder:'v1'}})});id=f.id;}if(!id)throw Error('Drive chưa xác nhận thư mục.');d.folderId=id;await persist();return id;}
async function uploadRecord(rec){let folder=await ensureFolder();try{for(let role of ['original','marked']){let revision=role==='marked'?rec.updated:rec.created;if(rec.drive?.[role]&&rec.drive[role+'Revision']===revision)continue;let tag=rec.id+'_'+role+'_'+revision,q="trashed=false and appProperties has { key='chamthiUpload' and value='"+tag+"' }",found=await driveFetch('drive/v3/files?q='+encodeURIComponent(q)+'&fields=files(id)');let id=found.files?.[0]?.id;if(!id){let boundary='ct_'+uid(),name=`${rec.sbd}_${rec.code}_${rec.id.slice(0,8)}_${role==='original'?'Goc':'Cham'}.jpg`,meta={name,parents:[folder],appProperties:{chamthiUpload:tag,examId:rec.examId}},body=new Blob([`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(meta)}\r\n--${boundary}\r\nContent-Type: image/jpeg\r\n\r\n`,rec[role],`\r\n--${boundary}--`]);let f=await driveFetch('upload/drive/v3/files?uploadType=multipart&fields=id',{method:'POST',headers:{'Content-Type':'multipart/related; boundary='+boundary},body});id=f.id;}if(!id)throw Error('Drive chưa xác nhận tệp.');rec.drive??={};rec.drive[role]=id;rec.drive[role+'Revision']=revision;rec.drive.error='';await put('records',rec);}}catch(e){rec.drive??={};rec.drive.error=e.message;await put('records',rec);throw e;}}
async function syncDrive(){if(!token)throw Error('Cần đăng nhập Google trước khi tải ảnh.');let pending=list().filter(r=>!r.drive?.marked||!r.drive?.original||r.drive?.markedRevision!==r.updated);if(!pending.length){toast('Tất cả bài đã có đủ ảnh trên Drive.');return;}for(let[i,r]of pending.entries()){toast(`Đang tải bài ${i+1}/${pending.length}…`);await uploadRecord(r);}toast(`Đã tải đủ ảnh của ${pending.length} bài lên Drive.`);render();}
async function regrade(){cloudGuard(false,true);let a=list(),n=0;for(let r of a){if(r.cloudSummary){let full=await downloadRecord(state.examId,r.cloudRecordId||r.id);full.cloudRecordId=r.cloudRecordId||r.id;full.id=r.id;full.cloudAccount=cloudUser.id;Object.assign(r,full);}if(!completeKey(state.keys[r.code],state.cfg)||r.cfg.template!==state.cfg.template)continue;let before=r.result;r.result=grade(r.answers,state.keys[r.code],state.cfg);r.cfg=structuredClone(state.cfg);r.key=structuredClone(state.keys[r.code]);r.version=state.cfg.version;r.updated=now();r.edits??=[];r.edits.push({at:now(),text:'Chấm lại theo đáp án phiên bản '+state.cfg.version,before,after:r.result});let im=await loadImage(r.upright),c=canvas(im.width,im.height);c.getContext('2d').drawImage(im,0,0);r.marked=await toBlob(annotate(c,templates[r.cfg.template],r.groups,r.result,{sbd:r.sbd,code:r.code,name:r.name},r.edits));r.drive={...r.drive,marked:'',error:'Cần tải lại ảnh theo điểm mới.'};r.status='draft';await put('records',r);n++;}toast(`Đã tính lại ${n} bài, chuyển sang chờ duyệt trước khi chốt lại.`);render();}
function validateConfig(c){for(let[n,max]of [['mc',40],['tf',8],['sa',6],['decimals',3]])if(!Number.isInteger(c[n])||c[n]<0||c[n]>max)throw Error('Cấu hình '+n+' không hợp lệ.');if(c.mc+c.tf+c.sa===0)throw Error('Cần ít nhất một câu để chấm.');for(let n of ['mcPoint','saPoint','tfPoint','tolerance'])if(!Number.isFinite(c[n])||c[n]<0)throw Error('Điểm hoặc sai số không hợp lệ.');if(!Array.isArray(c.tfTable)||c.tfTable.length!==5||c.tfTable.some(x=>!Number.isFinite(x)||x<0))throw Error('Bảng điểm đúng–sai không hợp lệ.');if(!['table','each'].includes(c.tfMode)||!templates[c.template])throw Error('Chế độ hoặc mẫu phiếu không hợp lệ.');if(!Number.isFinite(c.threshold)||c.threshold<.3||c.threshold>.85)throw Error('Ngưỡng nhận dạng cần từ 0,30 đến 0,85.');}
const actions={
 'sync-cloud':async()=>{await persist();cloudQueue?.retry(list());await refreshCloudRecords();render();toast('Đã tải dữ liệu online; bài trên thiết bị đang được đồng bộ.');},
 'pull-cloud':async()=>{let{exam}=await api('exams/'+state.examId);await putLocal('meta',{...state,id:'recovery:'+state.id+':'+Date.now()});state.cfg=exam.cfg;state.roster=exam.roster;state.keys=exam.keys;state.cloud=cloudInfo(exam);state.cloud.snapshot=setupFingerprint(state);cloudStateError='';await putLocal('meta',state);render();toast('Đã tải cấu hình online mới nhất.');},
 'publish-cloud':async()=>{if(state.cloud)throw Error('Kỳ thi này đã online.');showModal(`<h2>Đưa kỳ thi lên online</h2><p>Tạo bản sao cấu hình, học sinh, đáp án và bài làm của kỳ thi hiện tại. Bản trên thiết bị được giữ nguyên.</p><form id="publishCloudForm"><label for="cloudScope">Cách quản lý</label><select id="cloudScope" name="scope"><option value="private">Kỳ thi riêng của tôi</option><option value="shared">Kỳ thi chung của tổ / trường</option></select><p class="small">Ảnh và bài làm sẽ được tải lên kho online của kỳ thi. Với kỳ thi chung, người phụ trách phân công giáo viên sau khi tạo.</p><button type="submit">Tạo bản online & đồng bộ</button></form>`);},

 'load-setup':()=>$('#examSetupFile').click(),'go-scan':()=>{resumeCamera=page()==='review';location.hash='scan';},'go-import':()=>{keyTab='students';location.hash='exam';render();},'exam-tab':e=>{keyTab=e.dataset.tab;render();},'download-template':sampleWorkbook,
 'new-exam':async()=>{if(state.cloud){location.href="./team.html";return;}let old=state,archives={...old.archives};archives[old.examId]={examId:old.examId,cfg:old.cfg,roster:old.roster,keys:old.keys};state={...fresh(),drive:old.drive,archives};await persist();keyTab='settings';current=null;render();toast('Đã tạo kỳ thi mới. Có thể chuyển lại kỳ thi cũ trong danh sách.');},
 'preview-template':()=>showModal(`<h2>${templates[state.cfg.template].name}</h2><img src="./mau-${state.cfg.template}.png" alt="Mẫu phiếu đang dùng">`),
 'add-code':()=>{if(state.cfg.locked)throw Error('Đáp án đang khóa.');showModal('<h2>Thêm mã đề</h2><form id="addCodeForm"><label for="newCode">Mã đề gồm 4 chữ số</label><input id="newCode" name="code" required pattern="[0-9]{1,4}" maxlength="4" inputmode="numeric"><button type="submit" style="margin:15px 0">Thêm mã đề</button></form>');},
 'start-camera':startCamera,'stop-camera':()=>{stopCamera();render();},capture:()=>capture(),'pick-image':()=>$('#photoFile').click(),demo,
 'manual-corners':manualMode,'reset-corners':manualMode,'apply-corners':async()=>{if(manualCorners.length!==4)throw Error('Cần chọn đủ 4 góc.');$('#modal').close();await scanBlob(rawForCorners,manualCorners);},
 'rotate-raw':async()=>{let im=await loadImage(rawForCorners),c=canvas(im.height,im.width),x=c.getContext('2d');x.translate(c.width,0);x.rotate(Math.PI/2);x.drawImage(im,0,0);rawForCorners=await toBlob(c);$('#modal').close();await scanBlob(rawForCorners);},
 'rotate-image':async()=>{rawForCorners=current.original;await actions['rotate-raw']();},
 'download-marked':async()=>{if(!current)throw Error('Chưa có ảnh.');saveFile(await toBlob(current.annotated),`${current.demo?'MinhHoa_':''}${current.sbd}_${current.code}_Cham.jpg`);},
 'download-original':()=>saveFile(current.original,'Anh_goc_'+current.sbd+'.jpg'),'save-final':()=>saveCurrent('final'),'save-draft':()=>saveCurrent('draft'),'open-record':e=>openRecord(e.dataset.id),
 'export-results':exportResults,backup,restore:()=>$('#restoreFile').click(),'connect-drive':connectDrive,'disconnect-drive':()=>{token=null;render();toast('Đã ngắt phiên kết nối trên web.');},'sync-drive':syncDrive,regrade,
};
document.addEventListener('click',async e=>{let b=e.target.closest('[data-action]');if(!b)return;if(b.disabled)return;let action=actions[b.dataset.action];if(!action)return;b.disabled=true;try{await action(b);}catch(err){toast(err.message);if(err.message?.includes('\n'))showModal('<h2>Cần kiểm tra dữ liệu</h2><p style="white-space:pre-line">'+esc(err.message)+'</p>');}finally{b.disabled=false;}});
document.addEventListener('submit',async e=>{e.preventDefault();try{let f=new FormData(e.target);if(e.target.id==='publishCloudForm'){let {user}=await api('me'),{exam}=await api('exams',{method:'POST',body:JSON.stringify({scope:f.get('scope'),cfg:state.cfg,roster:state.roster,keys:state.keys})});let online={...state,id:'cloud:'+user.id+':'+exam.id,examId:exam.id,cfg:exam.cfg,cloud:cloudInfo(exam),archives:{}};online.cloud.snapshot=setupFingerprint(online);await putLocal('meta',online);for(let r of list()){let copy={...r,id:uid(),examId:exam.id,status:'draft',cfg:exam.cfg,version:exam.version,cloudExam:true,cloudAccount:user.id,cloudRecordId:undefined,cloudRevision:0,cloudStamp:'',cloudError:'',drive:{},created:now(),updated:now()};await putLocal('records',copy);}location.href='./index.html?cloud='+exam.id+'#results';return;}if(e.target.id==='importSheetForm'){if(!pendingWorkbook)throw Error('Chọn lại file Excel.');await applyWorkbook(pendingWorkbook,{rosterSheet:String(f.get('rosterSheet')||'')});}if(e.target.id==='configForm'){cloudGuard(true);let c=structuredClone(state.cfg);if(!c.locked){for(let n of ['name','template','tfMode'])c[n]=String(f.get(n));for(let n of ['mc','tf','sa','mcPoint','saPoint','tfPoint','decimals','tolerance','threshold'])c[n]=Number(f.get(n));c.tfTable=Array.from({length:5},(_,i)=>Number(f.get('tf'+i)));c.numeric=f.get('numeric')==='yes';validateConfig(c);c.version++;}c.locked=f.has('locked');state.cfg=c;await persist();render();toast(c.locked?'Đã lưu và khóa cài đặt.':'Đã lưu cài đặt.');}if(e.target.id==='addCodeForm'){cloudGuard(true);let code=String(f.get('code')).padStart(4,'0');if(state.keys[code])throw Error('Mã đề đã tồn tại.');state.keys[code]={mc:[],tf:Array.from({length:state.cfg.tf},()=>[]),sa:[]};activeCode=code;await persist();$('#modal').close();render();}if(e.target.id==='keyForm'){cloudGuard(true);if(state.cfg.locked)throw Error('Đáp án đang khóa.');let key={mc:[],tf:[],sa:[]};for(let q=0;q<state.cfg.mc;q++)key.mc[q]=String(f.get('mc_'+q)||'');for(let q=0;q<state.cfg.tf;q++)key.tf[q]=String(f.get('tf_'+q)||'').toUpperCase().split('').map(tfValue);for(let q=0;q<state.cfg.sa;q++){key.sa[q]=String(f.get('sa_'+q)||'').replace('.',',');if(!shortValid(key.sa[q]))throw Error('Phần III câu '+(q+1)+': đáp án không biểu diễn được trên 4 ô.');}if(!completeKey(key,state.cfg))throw Error('Cần nhập đủ đáp án.');state.keys[activeCode]=key;state.cfg.version++;await persist();toast('Đã lưu đáp án.');render();}if(e.target.id==='reviewForm')parseReview(e.target);if(e.target.id==='driveForm'){let clientId=String(f.get('clientId')||'').trim(),folderName=String(f.get('folderName')||'').trim();if(!clientId.endsWith('.apps.googleusercontent.com'))throw Error('OAuth Client ID chưa đúng định dạng.');if(state.drive.folderName!==folderName||state.drive.clientId!==clientId)state.drive.folderId='';if(state.drive.clientId!==clientId)token=null;state.drive={...state.drive,clientId,folderName};await persist();toast('Đã lưu cấu hình.');render();}}catch(err){toast(err.message);}});
document.addEventListener('change',async e=>{try{if(['resultClass','resultRoom','resultTeacher','resultStatus'].includes(e.target.id)){if(e.target.id==='resultClass')resultClass=e.target.value;if(e.target.id==='resultRoom')resultRoom=e.target.value;if(e.target.id==='resultTeacher')resultTeacher=e.target.value;if(e.target.id==='resultStatus')resultStatus=e.target.value;render();}if(e.target.id==='batchMode'){batchMode=e.target.checked;if(batchMode){cameraAuto=true;if($('#autoCapture'))$('#autoCapture').checked=true;}cameraSession?.reset();if($('#batchProgress'))$('#batchProgress').textContent=batchMode?'Quét liên tục: giữ yên '+batchDelay+' giây; lấy phiếu ra sau mỗi lần chụp.':'Chế độ duyệt từng phiếu.';}if(e.target.id==='batchDelay'){batchDelay=Number(e.target.value)===5?5:3;cameraSession?.reset();if(batchMode&&$('#batchProgress'))$('#batchProgress').textContent='Quét liên tục: giữ yên '+batchDelay+' giây; lấy phiếu ra sau mỗi lần chụp.';}if(e.target.id==='autoCapture'){cameraAuto=e.target.checked;cameraSession?.reset();}if(e.target.id==='examSelect'){if(state.cloud)throw Error('Đổi kỳ thi online trong Danh sách kỳ thi.');let target=state.archives?.[e.target.value];if(target){let archives={...state.archives,[state.examId]:{examId:state.examId,cfg:state.cfg,roster:state.roster,keys:state.keys}};state={...state,...target,archives};current=null;await persist();render();}}if(e.target.id==='excelFile'&&e.target.files[0]){cloudGuard(true);await importDataFile(e.target.files[0],{excel:importExcel,json:restore});}if(e.target.id==='photoFile'&&e.target.files[0])await scanBlob(e.target.files[0]);if(e.target.id==='examSetupFile'&&e.target.files[0])await restore(e.target.files[0]);if(e.target.id==='restoreFile'&&e.target.files[0])await restore(e.target.files[0]);if(e.target.id==='codeSelect'){activeCode=e.target.value;render();}if(e.target.id==='reviewAccepted'&&current)current.accepted=e.target.checked;}catch(err){showModal('<h2>Cần kiểm tra</h2><p style="white-space:pre-line">'+esc(err.message)+'</p>');}finally{if(e.target.type==='file')e.target.value='';}});
document.addEventListener('input',e=>{if(e.target.id==='resultSearch'){let pos=e.target.selectionStart;resultQuery=e.target.value;$('#app').innerHTML=cloudBanner()+resultsView();syncBadge();$('#resultSearch').focus();$('#resultSearch').setSelectionRange(pos,pos);}if(e.target.closest('#reviewForm')&&current){current.accepted=false;if($('#reviewAccepted'))$('#reviewAccepted').checked=false;}});
$('#closeModal').onclick=()=>$('#modal').close();window.addEventListener('hashchange',render);window.addEventListener('pagehide',stopCamera);
try{db=await new Promise((res,rej)=>{let r=indexedDB.open('chamthi-pages:'+new URL('.',location.href).pathname,1);r.onupgradeneeded=()=>{r.result.createObjectStore('meta',{keyPath:'id'});r.result.createObjectStore('records',{keyPath:'id'});};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});state=await request(db.transaction('meta').objectStore('meta').get('workspace'))||fresh();records=await request(db.transaction('records').objectStore('records').getAll());templates=await(await fetch('./templates.json?v=local-grid-20261103')).json();keyTab='settings';let cloudId=new URL(location.href).searchParams.get('cloud');if(cloudId)toast('GitHub Pages chỉ hỗ trợ chấm trên thiết bị. Mở bản có backend để dùng kỳ thi chung.');cloudQueue=createUploadQueue({load:async id=>request(db.transaction('records').objectStore('records').get(id)),save:async rec=>{await putLocal('records',rec);records=records.filter(r=>r.id!==rec.id);records.push(rec);},notify:message=>{if(message)toast(message);syncBadge();}});await putLocal('meta',state);render();if(state.cloud)cloudQueue.retry(list());window.addEventListener('online',()=>{if(state.cloud)cloudQueue.retry(list());});setInterval(async()=>{if(!state.cloud||busy||document.hidden)return;try{let{exam}=await api('exams/'+state.examId);if(exam.closed!==state.cloud.closed){state.cloud.closed=exam.closed;stopCamera();render();toast(exam.closed?'Người phụ trách đã đóng kỳ thi.':'Kỳ thi đã được mở lại.');}if(exam.version!==state.cfg.version&&!state.cloud.stale){state.cloud.stale=true;cloudStateError='Đáp án online đã đổi. Tải cấu hình mới trước khi tiếp tục.';stopCamera();render();}state.cloud.role=exam.role;state.cloud.assignment=exam.assignment;applyCloudPermissions();}catch(error){if(error.status===401||error.status===403){stopCamera();location.href='./team.html';}}},30000);}catch(e){$('#app').innerHTML='<div class="card"><h1>Không mở được dữ liệu</h1><p>'+esc(e.message)+'</p><p>Kiểm tra đăng nhập, quyền truy cập kỳ thi và kết nối mạng rồi tải lại trang.</p><a href="./team.html">Kỳ thi online</a> · <a href="./index.html">Dữ liệu trên thiết bị</a></div>';}
